import{_ as l,o as t,c as e,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"2019-03-11:: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-03-11:: Ceph Orchestration Meeting","date":"2019-03-11T00:00:00.000Z","updated":"2019-04-16T00:00:00.000Z","tags":["Ceph","Orchestrator","REST API","TLS","LSM 储存库"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-03-11_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-03-11_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),a={name:"posts/2019/2019-03-11_-_-_Ceph_Orchestration_Meeting.md"};function s(n,i,o,_,p,u){return t(),e("div",null,[...i[0]||(i[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年3月11日</p><p><strong>参会人员</strong>： Travis, Natalie, Jamaica, Dipsy, Sage, Aaron, Sebastian 等</p><p><strong>会议主题</strong>： Ceph Orchestrator 项目进展及问题讨论</p><p><strong>关键细节</strong>：</p><ul><li>Travis 因故缺席会议。</li><li>项目进度： <ul><li>Travis 正在处理两个 PR，一个用于内存自动调整，另一个用于使用 miss abuser 运行服务。</li><li>Natalie 正在修改 Ansible Runner 服务以支持 TLS。</li><li>Sage 正在解决本地化配置选项的问题。</li><li>Aaron 正在处理 Nautilus 的发布候选版本。</li><li>Sebastian 正在解决 LSM 储存库版本问题。</li></ul></li><li>问题讨论： <ul><li><strong>REST API 访问</strong>： 在尝试在仪表板中集成 Surface Cozy 时，出现了一个问题，需要为仪表板提供不验证 SSL 证书的选项。讨论了在服务描述符类中如何存储此类信息，以及是否应该在 Orchestrator 中添加此选项。</li><li><strong>TLS 支持</strong>： 讨论了在 Orchestrator 中支持 TLS 的必要性，并决定在 Ansible Runner 服务中实现。</li><li><strong>LSM 储存库版本</strong>： 讨论了将 LSM 储存库的最新版本集成到 SEF 容器镜像中的必要性。</li></ul></li><li>决定事项： <ul><li>Travis 将合并一个关于内存自动调整的 PR。</li><li>Natalie 将继续修改 Ansible Runner 服务以支持 TLS。</li><li>Sage 将继续解决本地化配置选项的问题。</li><li>Aaron 将解决 Nautilus 发布候选版本的问题。</li><li>Sebastian 将解决 LSM 储存库版本问题。</li></ul></li><li>后续行动计划： <ul><li>项目组成员将继续推进各自的工作，并定期在会议中汇报进展。</li><li>讨论的问题将根据需要进一步讨论并解决。</li></ul></li></ul><p><strong>关键词</strong>：</p><ul><li>Ceph Orchestrator</li><li>REST API</li><li>TLS</li><li>LSM 储存库</li><li>PR</li><li>发布候选版本</li><li>仪表板</li><li>Orchestrator</li><li>配置选项</li><li>安全性</li></ul><p><strong>分析与改进</strong>：</p><ol><li>原总结准确反映了会议的关键细节，包括项目进度、问题讨论和决定事项。</li><li>原总结遗漏了 Travis 提到的关于 Nautilus 发布候选版本的延迟问题，以及后续的讨论和分析。</li><li>改进后的总结增加了对 Travis 提到的问题的描述，并保持了所有关键细节的完整性。</li><li>关键词列表已更新，以反映会议中讨论的技术焦点。</li></ol>',10)])])}const S=l(a,[["render",s]]);export{g as __pageData,S as default};
